@Override
public Mono<User> createUser(User user, Set<String> roleNames) {
    Assert.notNull(user, "User must not be null");
    Assert.notNull(roleNames, "Roles must not be null");
    return client.fetch(User.class, user.getMetadata().getName())
            .hasElement()
            .flatMap(hasUser -> {
                if (hasUser) {
                    return Mono.error(new DuplicateNameException(
                            "User name is already in use", null, "problemDetail.user.duplicateName", new Object[] {
                                user.getMetadata().getName()
                            }));
                }
                // Check if all roles exist
                return Flux.fromIterable(roleNames)
                        .flatMap(roleName -> client.fetch(Role.class, roleName)
                                .switchIfEmpty(Mono.error(() ->
                                        new ServerWebInputException("Role [" + roleName + "] is not found."))))
                        .then();
            })
            .then(extensionGetter
                    .getExtensions(UserPreCreatingHandler.class)
                    .concatMap(handler -> handler.preCreating(user))
                    .then(Mono.defer(() -> client.create(user)
                            .flatMap(
                                    newUser -> grantRoles(user.getMetadata().getName(), roleNames))))
                    .flatMap(createdUser -> extensionGetter
                            .getExtensions(UserPostCreatingHandler.class)
                            .concatMap(handler -> handler.postCreating(createdUser))
                            .then()
                            .thenReturn(createdUser)));
}

