package run.halo.app.content.impl;

import java.time.Clock;
import java.util.HashMap;
import java.util.Objects;
import org.apache.commons.lang3.StringUtils;
import org.jspecify.annotations.Nullable;
import org.springframework.stereotype.Service;
import reactor.core.publisher.Mono;
import run.halo.app.content.Content;
import run.halo.app.content.PatchUtils;
import run.halo.app.content.SnapshotService;
import run.halo.app.core.extension.content.Snapshot;
import run.halo.app.extension.ReactiveExtensionClient;

@Service
public class SnapshotServiceImpl implements SnapshotService {

    private final ReactiveExtensionClient client;

    private final Clock clock;

    public SnapshotServiceImpl(ReactiveExtensionClient client) {
        this.client = client;
        this.clock = Clock.systemDefaultZone();
    }

    @Override
    public Mono<Snapshot> getBy(String snapshotName) {
        return client.get(Snapshot.class, snapshotName);
    }

    @Override
    public Mono<Snapshot> getPatchedBy(String snapshotName, String baseSnapshotName) {
        if (StringUtils.isBlank(snapshotName) || StringUtils.isBlank(baseSnapshotName)) {
            return Mono.empty();
        }

        return client.fetch(Snapshot.class, baseSnapshotName)
                .filter(Snapshot::isBaseSnapshot)
                .switchIfEmpty(Mono.error(() ->
                        new IllegalArgumentException("The snapshot " + baseSnapshotName + " is not a base snapshot.")))
                .flatMap(baseSnapshot -> Mono.defer(() -> {
                            if (Objects.equals(snapshotName, baseSnapshotName)) {
                                return Mono.just(baseSnapshot);
                            }
                            return client.fetch(Snapshot.class, snapshotName);
                        })
                        .doOnNext(snapshot -> {
                            var baseRaw = baseSnapshot.getSpec().getRawPatch();
                            var baseContent = baseSnapshot.getSpec().getContentPatch();

                            var rawPatch = snapshot.getSpec().getRawPatch();
                            var contentPatch = snapshot.getSpec().getContentPatch();

                            var annotations = snapshot.getMetadata().getAnnotations();
                            if (annotations == null) {
                                annotations = new HashMap<>();
                                snapshot.getMetadata().setAnnotations(annotations);
                            }

                            String patchedContent = baseContent;
                            String patchedRaw = baseRaw;
                            if (!Objects.equals(snapshot, baseSnapshot)) {
                                patchedContent = PatchUtils.applyPatch(baseContent, contentPatch);
                                patchedRaw = PatchUtils.applyPatch(baseRaw, rawPatch);
                            }

                            annotations.put(Snapshot.PATCHED_CONTENT_ANNO, patchedContent);
                            annotations.put(Snapshot.PATCHED_RAW_ANNO, patchedRaw);
                        }));
    }

    @Override
    public Mono<Snapshot> patchAndCreate(Snapshot snapshot, @Nullable Snapshot baseSnapshot, Content content) {
        return Mono.just(snapshot)
                .doOnNext(s -> this.patch(s, baseSnapshot, content))
                .flatMap(client::create);
    }

    @Override
    public Mono<Snapshot> patchAndUpdate(Snapshot snapshot, Snapshot baseSnapshot, Content content) {
        return Mono.just(snapshot)
                .doOnNext(s -> this.patch(s, baseSnapshot, content))
                .flatMap(client::update);
    }

    private void patch(Snapshot snapshot, @Nullable Snapshot baseSnapshot, Content content) {
        var annotations = snapshot.getMetadata().getAnnotations();
        if (annotations != null) {
            annotations.remove(Snapshot.PATCHED_CONTENT_ANNO);
            annotations.remove(Snapshot.PATCHED_RAW_ANNO);
        }
        var spec = snapshot.getSpec();
        if (spec == null) {
            spec = new Snapshot.SnapShotSpec();
        }
        spec.setRawType(content.rawType());
        if (baseSnapshot == null || Objects.equals(snapshot, baseSnapshot)) {
            // indicate the snapshot is a base snapshot
            // update raw and content directly
            spec.setRawPatch(content.raw());
            spec.setContentPatch(content.content());
        } else {
            // apply the patch and set the raw and content
            var baseSpec = baseSnapshot.getSpec();
            var baseContent = baseSpec.getContentPatch();
            var baseRaw = baseSpec.getRawPatch();

            var rawPatch = PatchUtils.diffToJsonPatch(baseRaw, content.raw());
            var contentPatch = PatchUtils.diffToJsonPatch(baseContent, content.content());
            spec.setRawPatch(rawPatch);
            spec.setContentPatch(contentPatch);
        }
        spec.setLastModifyTime(clock.instant());
    }
}

package run.halo.app.content.comment;

import static run.halo.app.extension.index.query.Queries.*;

import java.time.Duration;
import java.time.Instant;
import java.util.function.Function;
import org.apache.commons.lang3.BooleanUtils;
import org.springframework.dao.OptimisticLockingFailureException;
import org.springframework.data.domain.Sort;
import org.springframework.stereotype.Component;
import org.springframework.util.Assert;
import org.springframework.web.server.ServerWebInputException;
import reactor.core.publisher.Flux;
import reactor.core.publisher.Mono;
import reactor.util.retry.Retry;
import run.halo.app.core.counter.CounterService;
import run.halo.app.core.extension.content.Comment;
import run.halo.app.core.user.service.RoleService;
import run.halo.app.core.user.service.UserService;
import run.halo.app.extension.*;
import run.halo.app.extension.router.selector.FieldSelector;
import run.halo.app.infra.SystemConfigFetcher;
import run.halo.app.infra.exception.AccessDeniedException;
import run.halo.app.plugin.extensionpoint.ExtensionGetter;

/**
 * Comment service implementation.
 *
 * @author guqing
 * @since 2.0.0
 */
@Component
public class CommentServiceImpl extends AbstractCommentService implements CommentService {

    private final ExtensionGetter extensionGetter;
    private final SystemConfigFetcher environmentFetcher;
    private final CommentPermalinkService permalinkService;

    public CommentServiceImpl(
            RoleService roleService,
            ReactiveExtensionClient client,
            UserService userService,
            CounterService counterService,
            ExtensionGetter extensionGetter,
            SystemConfigFetcher environmentFetcher,
            CommentPermalinkService permalinkService) {
        super(roleService, client, userService, counterService);
        this.extensionGetter = extensionGetter;
        this.environmentFetcher = environmentFetcher;
        this.permalinkService = permalinkService;
    }

    @Override
    public Mono<ListResult<ListedComment>> listComment(CommentQuery commentQuery) {
        return this.client
                .listBy(Comment.class, commentQuery.toListOptions(), commentQuery.toPageRequest())
                .flatMap(comments -> Flux.fromStream(comments.get().map(this::toListedComment))
                        .flatMapSequential(Function.identity())
                        .collectList()
                        .map(list ->
                                new ListResult<>(comments.getPage(), comments.getSize(), comments.getTotal(), list)));
    }

    @Override
    public Mono<Comment> create(Comment comment) {
        if (comment.getSpec() == null
                || comment.getSpec().getContent() == null
                || !isSafeHtml(comment.getSpec().getContent())) {
            return Mono.error(new ServerWebInputException("problemDetail.comment.content.unsafe"));
        }
        return environmentFetcher
                .fetchComment()
                .flatMap(commentSetting -> {
                    if (Boolean.FALSE.equals(commentSetting.getEnable())) {
                        return Mono.error(new AccessDeniedException(
                                "The comment function has been turned off.", "problemDetail.comment.turnedOff", null));
                    }
                    if (checkCommentOwner(comment, commentSetting.getSystemUserOnly())) {
                        return Mono.error(new AccessDeniedException(
                                "Allow only system users to comment.", "problemDetail.comment.systemUsersOnly", null));
                    }

                    if (comment.getSpec().getTop() == null) {
                        comment.getSpec().setTop(false);
                    }
                    if (comment.getSpec().getPriority() == null) {
                        comment.getSpec().setPriority(0);
                    }
                    comment.getSpec().setApproved(Boolean.FALSE.equals(commentSetting.getRequireReviewForNew()));

                    if (BooleanUtils.isTrue(comment.getSpec().getApproved())
                            && comment.getSpec().getApprovedTime() == null) {
                        comment.getSpec().setApprovedTime(Instant.now());
                    }

                    if (comment.getSpec().getCreationTime() == null) {
                        comment.getSpec().setCreationTime(Instant.now());
                    }

                    if (comment.getSpec().getHidden() == null) {
                        comment.getSpec().setHidden(false);
                    }

                    return Mono.just(comment);
                })
                .flatMap(populatedComment -> Mono.when(
                                populateOwner(populatedComment), populateApproveState(populatedComment))
                        .thenReturn(populatedComment))
                .flatMap(client::create);
    }

    @Override
    public Mono<Comment> updateContent(String name, CommentContentRequest request) {
        return client.get(Comment.class, name).flatMap(comment -> {
            updateContent(comment.getSpec(), comment.getMetadata(), request);
            return client.update(comment);
        });
    }

    private Mono<Void> populateApproveState(Comment comment) {
        return hasCommentManagePermission()
                .filter(Boolean::booleanValue)
                .doOnNext(hasPermission -> {
                    comment.getSpec().setApproved(true);
                    comment.getSpec().setApprovedTime(Instant.now());
                })
                .then();
    }

    Mono<Void> populateOwner(Comment comment) {
        if (comment.getSpec().getOwner() != null) {
            return Mono.empty();
        }
        return fetchCurrentUser()
                .switchIfEmpty(Mono.error(new IllegalStateException("The owner must not be null.")))
                .map(this::toCommentOwner)
                .doOnNext(owner -> comment.getSpec().setOwner(owner))
                .then();
    }

    @Override
    public Mono<Void> removeBySubject(Ref subjectRef) {
        Assert.notNull(subjectRef, "The subjectRef must not be null.");
        return cleanupComments(subjectRef, 200);
    }

    private Mono<Void> cleanupComments(Ref subjectRef, int batchSize) {
        // ascending order by creation time and name
        final var pageRequest =
                PageRequestImpl.of(1, batchSize, Sort.by("metadata.creationTimestamp", "metadata.name"));
        // forever loop first page until no more to delete
        return listCommentsByRef(subjectRef, pageRequest)
                .flatMap(page -> Flux.fromIterable(page.getItems())
                        .flatMap(this::deleteWithRetry)
                        .then(page.hasNext() ? cleanupComments(subjectRef, batchSize) : Mono.empty()));
    }

    private Mono<Comment> deleteWithRetry(Comment item) {
        return client.delete(item)
                .onErrorResume(
                        OptimisticLockingFailureException.class,
                        e -> attemptToDelete(item.getMetadata().getName()));
    }

    private Mono<Comment> attemptToDelete(String name) {
        return Mono.defer(() -> client.fetch(Comment.class, name).flatMap(client::delete))
                .retryWhen(Retry.backoff(8, Duration.ofMillis(100))
                        .filter(OptimisticLockingFailureException.class::isInstance));
    }

    Mono<ListResult<Comment>> listCommentsByRef(Ref subjectRef, PageRequest pageRequest) {
        var listOptions = new ListOptions();
        listOptions.setFieldSelector(FieldSelector.of(and(
                equal("spec.subjectRef", Comment.toSubjectRefKey(subjectRef)), isNull("metadata.deletionTimestamp"))));
        return client.listBy(Comment.class, listOptions, pageRequest);
    }

    private boolean checkCommentOwner(Comment comment, Boolean onlySystemUser) {
        Comment.CommentOwner owner = comment.getSpec().getOwner();
        if (Boolean.TRUE.equals(onlySystemUser)) {
            return owner != null && Comment.CommentOwner.KIND_EMAIL.equals(owner.getKind());
        }
        return false;
    }

    private Mono<ListedComment> toListedComment(Comment comment) {
        var builder = ListedComment.builder().comment(comment);
        // not empty
        var ownerInfoMono = getOwnerInfo(comment.getSpec().getOwner()).doOnNext(builder::owner);
        var subjectMono = getCommentSubject(comment.getSpec().getSubjectRef()).doOnNext(builder::subject);
        var statsMono = fetchCommentStats(comment.getMetadata().getName()).doOnNext(builder::stats);
        var permalinkMono = permalinkService.getPermalink(comment).doOnNext(builder::permalink);
        return Mono.when(ownerInfoMono, subjectMono, statsMono, permalinkMono).then(Mono.fromSupplier(builder::build));
    }

    @SuppressWarnings("unchecked")
    Mono<Extension> getCommentSubject(Ref ref) {
        return extensionGetter
                .getExtensions(CommentSubject.class)
                .filter(subject -> subject.supports(ref))
                .next()
                .flatMap(subject -> subject.get(ref.getName()));
    }
}

