 * A default implementation of {@link ReplyService}.
 *
 * @author guqing
 * @since 2.0.0
 */
@Service
public class ReplyServiceImpl extends AbstractCommentService implements ReplyService {

    private final CommentPermalinkService permalinkService;

    private final Supplier<RequestRestrictedException> requestRestrictedExceptionSupplier =
            () -> new RequestRestrictedException("problemDetail.comment.waitingForApproval");

    public ReplyServiceImpl(
            RoleService roleService,
            ReactiveExtensionClient client,
            UserService userService,
            CounterService counterService,
            CommentPermalinkService permalinkService) {
        super(roleService, client, userService, counterService);
        this.permalinkService = permalinkService;
    }

    @Override
    public Mono<Reply> create(String commentName, Reply reply) {
        if (reply.getSpec() == null
                || reply.getSpec().getContent() == null
                || !isSafeHtml(reply.getSpec().getContent())) {
            return Mono.error(new ServerWebInputException("problemDetail.comment.content.unsafe"));
        }
        return client.get(Comment.class, commentName)
                .flatMap(this::approveComment)
                .filter(comment -> isTrue(comment.getSpec().getApproved()))
                .switchIfEmpty(Mono.error(requestRestrictedExceptionSupplier))
                .flatMap(comment -> prepareReply(comment, reply))
                .flatMap(this::doCreateReply);
    }

    private Mono<Reply> doCreateReply(Reply prepared) {
        var quotedReply = prepared.getSpec().getQuoteReply();
        if (StringUtils.isBlank(quotedReply)) {
            return client.create(prepared);
        }
        return approveReply(quotedReply)
                .filter(reply -> isTrue(reply.getSpec().getApproved()))
                .switchIfEmpty(Mono.error(requestRestrictedExceptionSupplier))
                .doOnNext(approvedQuoteReply -> prepared.getSpec()
                        .setHidden(isTrue(prepared.getSpec().getHidden())
                                || isTrue(approvedQuoteReply.getSpec().getHidden())))
                .flatMap(approvedQuoteReply -> client.create(prepared));
    }

    @Override
    public Mono<Reply> updateContent(String name, CommentContentRequest request) {
        return client.get(Reply.class, name).flatMap(reply -> {
            updateContent(reply.getSpec(), reply.getMetadata(), request);
            return client.update(reply);
        });
    }

    private Mono<Comment> approveComment(Comment comment) {
        return hasCommentManagePermission().flatMap(hasPermission -> {
            if (hasPermission) {
                return doApproveComment(comment);
            }
            return Mono.just(comment);
        });
    }

    private Mono<Comment> doApproveComment(Comment comment) {
        UnaryOperator<Comment> updateFunc = commentToUpdate -> {
            commentToUpdate.getSpec().setApproved(true);
            commentToUpdate.getSpec().setApprovedTime(Instant.now());
            return commentToUpdate;
        };
        return client.update(updateFunc.apply(comment))
                .onErrorResume(
                        OptimisticLockingFailureException.class,
                        e -> updateCommentWithRetry(comment.getMetadata().getName(), updateFunc));
    }

    private Mono<Reply> approveReply(String replyName) {
        return hasCommentManagePermission().flatMap(hasPermission -> {
            if (hasPermission) {
                return doApproveReply(replyName);
            }
            return client.get(Reply.class, replyName);
        });
    }

    private Mono<Reply> doApproveReply(String replyName) {
        return Mono.defer(() -> client.get(Reply.class, replyName).flatMap(reply -> {
                    reply.getSpec().setApproved(true);
                    reply.getSpec().setApprovedTime(Instant.now());
                    return client.update(reply);
                }))
                .retryWhen(Retry.backoff(8, Duration.ofMillis(100))
                        .filter(OptimisticLockingFailureException.class::isInstance));
    }

    private Mono<Comment> updateCommentWithRetry(String name, UnaryOperator<Comment> updateFunc) {
        return Mono.defer(() -> client.get(Comment.class, name).map(updateFunc).flatMap(client::update))
                .retryWhen(Retry.backoff(8, Duration.ofMillis(100))
                        .filter(OptimisticLockingFailureException.class::isInstance));
    }

    private Mono<Reply> prepareReply(Comment comment, Reply reply) {
        reply.getSpec().setCommentName(comment.getMetadata().getName());
        reply.getSpec()
                .setHidden(isTrue(reply.getSpec().getHidden())
                        || isTrue(comment.getSpec().getHidden()));
        if (reply.getSpec().getTop() == null) {
            reply.getSpec().setTop(false);
        }
        if (reply.getSpec().getPriority() == null) {
            reply.getSpec().setPriority(0);
        }
        if (reply.getSpec().getCreationTime() == null) {
            reply.getSpec().setCreationTime(Instant.now());
        }
        if (reply.getSpec().getApproved() == null) {
            reply.getSpec().setApproved(false);
        }
        if (isTrue(reply.getSpec().getApproved()) && reply.getSpec().getApprovedTime() == null) {
            reply.getSpec().setApprovedTime(Instant.now());
        }

        var steps = new ArrayList<Publisher<?>>();
        var approveItMono = hasCommentManagePermission()
                .filter(Boolean::booleanValue)
                .map(hasPermission -> {
                    reply.getSpec().setApproved(true);
                    reply.getSpec().setApprovedTime(Instant.now());
                    return hasPermission;
                });
        steps.add(approveItMono);

        var populateOwnerMono = fetchCurrentUser()
                .switchIfEmpty(Mono.error(new IllegalArgumentException("Reply owner must not be null.")))
                .doOnNext(user -> reply.getSpec().setOwner(toCommentOwner(user)));
        if (reply.getSpec().getOwner() == null) {
            steps.add(populateOwnerMono);
        }
        return Mono.when(steps).thenReturn(reply);
    }

    @Override
    public Mono<ListResult<ListedReply>> list(ReplyQuery query) {
        return client.listBy(Reply.class, query.toListOptions(), query.toPageRequest())
                .flatMap(list -> client.fetch(Comment.class, query.getCommentName())
                        .flatMap(comment ->
                                permalinkService.getSubjectUrl(comment.getSpec().getSubjectRef()))
                        .defaultIfEmpty("")
                        .flatMap(subjectUrl -> Flux.fromStream(list.get().map(this::toListedReply))
                                .flatMapSequential(Function.identity())
                                .doOnNext(item -> item.setPermalink(CommentPermalinkService.getPermalink(
                                        subjectUrl,
                                        query.getCommentName(),
                                        item.getReply().getMetadata().getName())))
                                .collectList()
                                .map(listedReplies -> new ListResult<>(
                                        list.getPage(), list.getSize(), list.getTotal(), listedReplies))));
    }

    @Override
    public Mono<Void> removeAllByComment(String commentName) {
        Assert.notNull(commentName, "The commentName must not be null.");
        return cleanupComments(commentName, 200);
    }

    private Mono<Void> cleanupComments(String commentName, int batchSize) {
        // ascending order by creation time and name
        final var pageRequest =
                PageRequestImpl.of(1, batchSize, Sort.by("metadata.creationTimestamp", "metadata.name"));
        // forever loop first page until no more to delete
        return listRepliesByComment(commentName, pageRequest)
                .flatMap(page -> Flux.fromIterable(page.getItems())
                        .flatMap(this::deleteWithRetry)
                        .then(page.hasNext() ? cleanupComments(commentName, batchSize) : Mono.empty()));
    }

    private Mono<Reply> deleteWithRetry(Reply item) {
        return client.delete(item)
                .onErrorResume(
                        OptimisticLockingFailureException.class,
                        e -> attemptToDelete(item.getMetadata().getName()));
    }

    private Mono<Reply> attemptToDelete(String name) {
        return Mono.defer(() -> client.fetch(Reply.class, name).flatMap(client::delete))
                .retryWhen(Retry.backoff(8, Duration.ofMillis(100))
                        .filter(OptimisticLockingFailureException.class::isInstance));
    }

    Mono<ListResult<Reply>> listRepliesByComment(String commentName, PageRequest pageRequest) {
        var listOptions = new ListOptions();
        listOptions.setFieldSelector(
                FieldSelector.of(and(equal("spec.commentName", commentName), isNull("metadata.deletionTimestamp"))));
        return client.listBy(Reply.class, listOptions, pageRequest);
    }

    private Mono<ListedReply> toListedReply(Reply reply) {
        ListedReply.ListedReplyBuilder builder = ListedReply.builder().reply(reply);
        return getOwnerInfo(reply.getSpec().getOwner())
                .map(ownerInfo -> {
                    builder.owner(ownerInfo);
                    return builder;
                })
                .map(ListedReply.ListedReplyBuilder::build)
                .flatMap(listedReply -> fetchReplyStats(reply.getMetadata().getName())
                        .doOnNext(listedReply::setStats)
                        .thenReturn(listedReply));
    }
}

package run.halo.app.security.authentication.twofactor;

import static io.swagger.v3.oas.annotations.media.Schema.RequiredMode.REQUIRED;
import static org.springdoc.core.fn.builders.apiresponse.Builder.responseBuilder;
import static org.springdoc.core.fn.builders.requestbody.Builder.requestBodyBuilder;
import static org.springdoc.webflux.core.fn.SpringdocRouteBuilder.route;
import static org.springframework.web.reactive.function.server.RequestPredicates.path;

import io.swagger.v3.oas.annotations.media.Schema;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import java.net.URI;
import lombok.Data;
import org.apache.commons.lang3.StringUtils;
import org.springframework.security.authentication.AnonymousAuthenticationToken;
import org.springframework.security.core.Authentication;
import org.springframework.security.core.context.ReactiveSecurityContextHolder;
import org.springframework.security.core.context.SecurityContext;
import org.springframework.security.crypto.password.PasswordEncoder;
import org.springframework.stereotype.Component;
import org.springframework.validation.Validator;
import org.springframework.web.reactive.function.server.RouterFunction;
import org.springframework.web.reactive.function.server.ServerRequest;
import org.springframework.web.reactive.function.server.ServerResponse;
import org.springframework.web.server.ServerWebInputException;
import org.springframework.web.util.UriComponentsBuilder;
import reactor.core.publisher.Mono;
import run.halo.app.core.extension.User;
import run.halo.app.core.extension.endpoint.CustomEndpoint;
import run.halo.app.core.user.service.UserService;
import run.halo.app.extension.GroupVersion;
import run.halo.app.extension.ReactiveExtensionClient;
import run.halo.app.infra.ExternalUrlSupplier;
import run.halo.app.infra.ValidationUtils;
import run.halo.app.infra.exception.AccessDeniedException;
import run.halo.app.infra.exception.RequestBodyValidationException;
import run.halo.app.infra.exception.UnsatisfiedAttributeValueException;
import run.halo.app.security.authentication.twofactor.totp.TotpAuthService;

@Component
public class TwoFactorAuthEndpoint implements CustomEndpoint {

    private final ReactiveExtensionClient client;

    private final UserService userService;

    private final TotpAuthService totpAuthService;

    private final Validator validator;

    private final PasswordEncoder passwordEncoder;

    private final ExternalUrlSupplier externalUrl;

    public TwoFactorAuthEndpoint(
            ReactiveExtensionClient client,
            UserService userService,
            TotpAuthService totpAuthService,
            Validator validator,
            PasswordEncoder passwordEncoder,
            ExternalUrlSupplier externalUrl) {
        this.client = client;
        this.userService = userService;
        this.totpAuthService = totpAuthService;
        this.validator = validator;
        this.passwordEncoder = passwordEncoder;
        this.externalUrl = externalUrl;
    }

    @Override
    public RouterFunction<ServerResponse> endpoint() {
        var tag = "TwoFactorAuthV1alpha1Uc";
        return route().nest(
                        path("/authentications/two-factor"),
                        () -> route().GET(
                                        "/settings",
                                        this::getTwoFactorSettings,
                                        builder -> builder.operationId("GetTwoFactorAuthenticationSettings")
                                                .tag(tag)
                                                .description("Get Two-factor authentication settings.")
                                                .response(
                                                        responseBuilder().implementation(TwoFactorAuthSettings.class)))
                                .PUT(
                                        "/settings/enabled",
                                        this::enableTwoFactor,
                                        builder -> builder.operationId("EnableTwoFactor")
                                                .tag(tag)
                                                .description("Enable Two-factor authentication")
                                                .requestBody(
                                                        requestBodyBuilder().implementation(PasswordRequest.class))
                                                .response(
                                                        responseBuilder().implementation(TwoFactorAuthSettings.class)))
                                .PUT(
                                        "/settings/disabled",
                                        this::disableTwoFactor,
                                        builder -> builder.operationId("DisableTwoFactor")
                                                .tag(tag)
                                                .description("Disable Two-factor authentication")
                                                .requestBody(
                                                        requestBodyBuilder().implementation(PasswordRequest.class))
                                                .response(
                                                        responseBuilder().implementation(TwoFactorAuthSettings.class)))
                                .POST(
                                        "/totp",
                                        this::configureTotp,
                                        builder -> builder.operationId("ConfigurerTotp")
                                                .tag(tag)
                                                .description("Configure a TOTP")
                                                .requestBody(
                                                        requestBodyBuilder().implementation(TotpRequest.class))
                                                .response(
                                                        responseBuilder().implementation(TwoFactorAuthSettings.class)))
                                .DELETE(
                                        "/totp/-",
                                        this::deleteTotp,
                                        builder -> builder.operationId("DeleteTotp")
                                                .tag(tag)
                                                .description("Delete the current user's configured TOTP authenticator "
                                                        + "after password verification.")
                                                .requestBody(
                                                        requestBodyBuilder().implementation(PasswordRequest.class))
                                                .response(
                                                        responseBuilder().implementation(TwoFactorAuthSettings.class)))
                                .GET(
                                        "/totp/auth-link",
                                        this::getTotpAuthLink,
                                        builder -> builder.operationId("GetTotpAuthLink")
                                                .tag(tag)
                                                .description("Get TOTP auth link, including secret")
                                                .response(responseBuilder().implementation(TotpAuthLinkResponse.class)))
                                .build())
                .build();
    }

    private Mono<ServerResponse> deleteTotp(ServerRequest request) {
        var totpDeleteRequestMono = request.bodyToMono(PasswordRequest.class)
                .switchIfEmpty(Mono.error(() -> new ServerWebInputException("Request body required")))
                .delayUntil(passwordRequest -> this.validateRequest(passwordRequest, "passwordRequest", request));

        var twoFactorAuthSettings = totpDeleteRequestMono.flatMap(passwordRequest -> getCurrentUser()
                .filter(user -> {
                    var rawPassword = passwordRequest.getPassword();
                    var encodedPassword = user.getSpec().getPassword();
                    return this.passwordEncoder.matches(rawPassword, encodedPassword);
                })
                .switchIfEmpty(Mono.error(
                        () -> new UnsatisfiedAttributeValueException("problemDetail.user.password.notMatch")))
                .delayUntil(user -> validateTotpCode(user, passwordRequest.getTotpCode()))
                .doOnNext(user -> {
                    var spec = user.getSpec();
                    spec.setTotpEncryptedSecret(null);
                })
                .flatMap(client::update)
                .map(TwoFactorUtils::getTwoFactorAuthSettings));
        return ServerResponse.ok().body(twoFactorAuthSettings, TwoFactorAuthSettings.class);
    }

    /** Password verification payload for changing two-factor authentication settings. */
    @Data
    public static class PasswordRequest {

        /** Current password of the authenticated user. */
        @Schema(requiredMode = REQUIRED)
        @NotBlank
        private String password;

        /** Current TOTP code, required when TOTP has already been configured. */
        private String totpCode;
    }

    private Mono<ServerResponse> disableTwoFactor(ServerRequest request) {
        return toggleTwoFactor(request, false);
    }

    private Mono<ServerResponse> enableTwoFactor(ServerRequest request) {
        return toggleTwoFactor(request, true);
    }

    private Mono<ServerResponse> toggleTwoFactor(ServerRequest request, boolean enabled) {
        return request.bodyToMono(PasswordRequest.class)
                .switchIfEmpty(Mono.error(() -> new ServerWebInputException("Request body required")))
                .delayUntil(passwordRequest -> this.validateRequest(passwordRequest, "passwordRequest", request))
                .flatMap(passwordRequest -> getCurrentUser()
                        .filter(user -> {
                            var encodedPassword = user.getSpec().getPassword();
                            var rawPassword = passwordRequest.getPassword();
                            return passwordEncoder.matches(rawPassword, encodedPassword);
                        })
                        .switchIfEmpty(Mono.error(
                                () -> new UnsatisfiedAttributeValueException("problemDetail.user.password.notMatch")))
                        .delayUntil(user -> validateTotpCode(user, passwordRequest.getTotpCode()))
                        .doOnNext(user -> user.getSpec().setTwoFactorAuthEnabled(enabled))
                        .flatMap(client::update)
                        .map(TwoFactorUtils::getTwoFactorAuthSettings))
                .flatMap(twoFactorAuthSettings -> ServerResponse.ok().bodyValue(twoFactorAuthSettings));
    }

    private Mono<ServerResponse> getTotpAuthLink(ServerRequest request) {
        var authLinkResponse = getCurrentUser().map(user -> {
            var username = user.getMetadata().getName();
            var url = externalUrl.getURL(request.exchange().getRequest());
            var authority = url.getAuthority();
            var authKeyId = username + ":" + authority;
            var rawSecret = totpAuthService.generateTotpSecret();
            var authLink = UriComponentsBuilder.fromUriString("otpauth://totp")
                    .path(authKeyId)
                    .queryParam("secret", rawSecret)
                    .queryParam("digits", 6)
                    .build()
                    .toUri();
            var authLinkResp = new TotpAuthLinkResponse();
            authLinkResp.setAuthLink(authLink);
            authLinkResp.setRawSecret(rawSecret);
            return authLinkResp;
        });

        return ServerResponse.ok().body(authLinkResponse, TotpAuthLinkResponse.class);
    }

    /** TOTP provisioning data for configuring an authenticator app. */
    @Data
    public static class TotpAuthLinkResponse {

        /** otpauth URI that can be encoded as a QR code. */
        @Schema(requiredMode = REQUIRED)
        private URI authLink;

        /** Raw TOTP secret for manual authenticator setup. */
        @Schema(requiredMode = REQUIRED)
        private String rawSecret;
    }

    private Mono<ServerResponse> configureTotp(ServerRequest request) {
        var totpRequestMono = request.bodyToMono(TotpRequest.class)
                .switchIfEmpty(Mono.error(() -> new ServerWebInputException("Request body required.")))
                .delayUntil(totpRequest -> this.validateRequest(totpRequest, "totp", request));

        var configuredUser = totpRequestMono.flatMap(totpRequest -> {
            // validate password
            return getCurrentUser()
                    .filter(user -> {
                        var encodedPassword = user.getSpec().getPassword();
                        var rawPassword = totpRequest.getPassword();
                        return passwordEncoder.matches(rawPassword, encodedPassword);
                    })
                    .switchIfEmpty(Mono.error(
                            () -> new UnsatisfiedAttributeValueException("problemDetail.user.password.notMatch")))
                    .delayUntil(user -> validateTotpCode(user, totpRequest.getCurrentTotpCode()))
                    .delayUntil(user -> {
                        var rawSecret = totpRequest.getSecret();
                        var encryptedSecret = totpAuthService.encryptSecret(rawSecret);
                        return validateTotpCode(encryptedSecret, totpRequest.getCode())
                                .then(Mono.fromRunnable(() -> user.getSpec().setTotpEncryptedSecret(encryptedSecret)));
                    })
                    .flatMap(client::update);
        });

        var twoFactorAuthSettings = configuredUser.map(TwoFactorUtils::getTwoFactorAuthSettings);

        return ServerResponse.ok().body(twoFactorAuthSettings, TwoFactorAuthSettings.class);
    }

    private Mono<Void> validateRequest(Object target, String name, ServerRequest request) {
        var bindingResult = ValidationUtils.validate(target, name, validator, request.exchange());
        if (bindingResult.hasErrors()) {
            return Mono.error(new RequestBodyValidationException(bindingResult));
        }
        return Mono.empty();
    }

    /** TOTP configuration payload. */
    @Data
    public static class TotpRequest {

        /** Raw TOTP secret returned by the auth-link endpoint. */
        @Schema(requiredMode = REQUIRED)
        @NotBlank
        private String secret;

        /** TOTP code generated from the new secret. */
        @Schema(requiredMode = REQUIRED)
        @NotNull
        private String code;

        /** Current password of the authenticated user. */
        @Schema(requiredMode = REQUIRED)
        @NotBlank
        private String password;

        /** Current TOTP code, required when replacing an existing TOTP authenticator. */
        private String currentTotpCode;
    }

    private Mono<Void> validateTotpCode(User user, String totpCode) {
        var totpEncryptedSecret = user.getSpec().getTotpEncryptedSecret();
        if (StringUtils.isBlank(totpEncryptedSecret)) {
            // TOTP is not configured, no need to validate
            return Mono.empty();
        }
        return validateTotpCode(totpEncryptedSecret, totpCode);
    }

    private Mono<Void> validateTotpCode(String totpEncryptedSecret, String totpCode) {
        if (StringUtils.isBlank(totpCode)) {
            return Mono.error(new UnsatisfiedAttributeValueException("problemDetail.user.twoFactor.code.required"));
        }
        int code;
        try {
            code = Integer.parseInt(totpCode);
        } catch (NumberFormatException e) {
            return Mono.error(new UnsatisfiedAttributeValueException("problemDetail.user.twoFactor.code.invalid"));
        }
        var rawSecret = totpAuthService.decryptSecret(totpEncryptedSecret);
        if (!totpAuthService.validateTotp(rawSecret, code)) {
            return Mono.error(new UnsatisfiedAttributeValueException("problemDetail.user.twoFactor.code.invalid"));
        }
        return Mono.empty();
    }

    private Mono<ServerResponse> getTwoFactorSettings(ServerRequest request) {
        return getCurrentUser()
                .map(TwoFactorUtils::getTwoFactorAuthSettings)
                .flatMap(settings -> ServerResponse.ok().bodyValue(settings));
    }

    private Mono<User> getCurrentUser() {
        return ReactiveSecurityContextHolder.getContext()
                .map(SecurityContext::getAuthentication)
                .filter(TwoFactorAuthEndpoint::isAuthenticatedUser)
                .switchIfEmpty(Mono.error(AccessDeniedException::new))
                .map(Authentication::getName)
                .flatMap(userService::getUser);
    }

    private static boolean isAuthenticatedUser(Authentication authentication) {
        return authentication != null && !(authentication instanceof AnonymousAuthenticationToken);
    }

    @Override
    public GroupVersion groupVersion() {
        return GroupVersion.parseAPIVersion("uc.api.security.halo.run/v1alpha1");
    }
}
